bond-energy-algorithm.pseudocode:
def bond(aa, x, y):
    if x is None or y is None:  # 경계 열은 0
        return 0
    return sum(aa[z][x] * aa[z][y] for z in range(len(aa)))

def cont(aa, i, k, j):  # Ai-Ak-Aj 배치 시 기여도
    return (2 * bond(aa, i, k) + 2 * bond(aa, k, j)
            - 2 * bond(aa, i, j))

def bea(aa):
    n = len(aa)
    order = [0, 1]  # 처음 두 열 배치
    for k in range(2, n):
        best_pos, best = 0, None
        for pos in range(len(order) + 1):
            left = order[pos - 1] if pos > 0 else None
            right = order[pos] if pos < len(order) else None
            c = cont(aa, left, k, right)
            if best is None or c > best:
                best_pos, best = pos, c
        order.insert(best_pos, k)
    return order  # 행도 같은 순서로 재배치 → CA
